  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  7→import { Phone, Mail, MapPin, FileText, Archive } from "lucide-react";
  8→import { toast } from "sonner";
  9→import type { Result } from "@/pages/Index";
 10→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 11→import type { HiringStage } from "@/hooks/useStageTracker";
 12→
 13→interface CandidateRowProps {
 14→  result: Result;
 15→  index: number;
 16→  isSelected: boolean;
 17→  isActive: boolean;
 18→  jobTitle?: string | null;
 19→  onSelect: (id: string) => void;
 20→  onToggleSelect: (resumeId: string) => void;
 21→  onDownload: (filePath: string, filename: string) => void;
 22→  onDismiss: (resumeId: string) => void;
 23→  formatCandidateName: (filename: string) => string;
 24→  currentStage?: HiringStage | null;
 25→  isDuplicate?: boolean;
 26→}
 27→
 28→const getScoreColor = (score: number) => {
 29→  if (score >= 70) return "bg-score-skills";
 30→  if (score >= 40) return "bg-warning";
 31→  return "bg-destructive";
 32→};
 33→
 34→const getScoreTextColor = (score: number) => {
 35→  if (score >= 70) return "text-score-skills";
 36→  if (score >= 40) return "text-warning";
 37→  return "text-destructive";
 38→};
 39→
 40→const STAGE_BADGE_CLASSES: Record<string, string> = {
 41→  applied: "border-border bg-muted/50 text-muted-foreground",
 42→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
 43→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
 44→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
 45→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
 46→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
 47→};
 48→
 49→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 50→  if (score >= 70) return { label: "Strong", variant: "success" };
 51→  if (score >= 40) return { label: "Good", variant: "warning" };
 52→  return { label: "Weak", variant: "destructive" };
 53→};
 54→
 55→const getRankDisplay = (index: number) => {
 56→  if (index < 3) {
 57→    const colors = [
 58→      "bg-score-overall text-white dark:text-white",
 59→      "bg-muted-foreground/60 text-white dark:text-white",
 60→      "bg-warning text-warning-foreground",
 61→    ];
 62→    return (
 63→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 64→        {index + 1}
 65→      </span>
 66→    );
 67→  }
 68→  return (
 69→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 70→      {index + 1}
 71→    </span>
 72→  );
 73→};
 74→
 75→const CandidateRow = ({
 76→  result: r,
 77→  index,
 78→  isSelected,
 79→  isActive,
 80→  jobTitle,
 81→  onSelect,
 82→  onToggleSelect,
 83→  onDownload,
 84→  onDismiss,
 85→  formatCandidateName,
 86→  currentStage,
 87→  isDuplicate,
 88→}: CandidateRowProps) => {
 89→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 90→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
 91→
 92→  return (
 93→    <>
 94→      <TableRow
 95→        className={`cursor-pointer transition-colors animate-in fade-in slide-in-from-bottom-1 duration-200 ${isActive ? "bg-primary/5 hover:bg-primary/5" : "hover:bg-muted/50"}`}
 96→        style={{ animationDelay: `${Math.min(index * 40, 400)}ms`, animationFillMode: "backwards" }}
 97→        onClick={() => !r.pending && onSelect(r.id)}
 98→      >
 99→        <TableCell onClick={(e) => e.stopPropagation()}>
100→          <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
101→        </TableCell>
102→        <TableCell className="text-center">
103→          {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
104→        </TableCell>
105→        <TableCell className="font-medium">
106→          <div className="flex flex-col gap-0.5">
107→            <div className="flex items-center gap-1.5 flex-wrap">
108→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
109→              {isDuplicate && (
110→                <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-orange-300 text-orange-600 bg-orange-50">
111→                  Duplicate
112→                </Badge>
113→              )}
114→              {!r.pending && currentStage && currentStage !== "applied" && (
115→                <Badge
116→                  variant="outline"
117→                  className={`text-[10px] px-1.5 py-0 h-4 capitalize border font-medium ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
118→                >
119→                  {currentStage}
120→                </Badge>
121→              )}
122→            </div>
123→            {r.candidate_location && (
124→              <span className="flex items-center gap-1 text-xs text-muted-foreground">
125→                <MapPin className="h-3 w-3" /> {r.candidate_location}
126→              </span>
127→            )}
128→          </div>
129→        </TableCell>
130→        <TableCell>
131→          {r.pending ? (
132→            <Badge variant="outline" className="text-xs">Pending</Badge>
133→          ) : (
134→            <div className="flex items-center gap-2">
135→              <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
136→                <div
137→                  className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
138→                  style={{ width: `${Math.min(r.overall_score, 100)}%` }}
139→                />
140→              </div>
141→              <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
142→                {r.overall_score?.toFixed(0)}%
143→              </span>
144→            </div>
145→          )}
146→        </TableCell>
147→        <TableCell>
148→          <div className="flex flex-wrap items-center gap-1">
149→            {!r.pending && strength && (
150→              <Badge variant={strength.variant} className="text-[10px]">{strength.label}</Badge>
151→            )}
152→            {!r.pending && r.scoring_version === "heuristic" && (
153→              <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium">Quick</span>
154→            )}
155→          </div>
156→        </TableCell>
157→        <TableCell>
158→          <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
159→            <TooltipProvider delayDuration={300}>
160→              {r.candidate_phone && (
161→                <Tooltip>
162→                  <TooltipTrigger asChild>
163→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
164→                      onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
165→                      <Phone className="h-3.5 w-3.5" />
166→                    </Button>
167→                  </TooltipTrigger>
168→                  <TooltipContent>{r.candidate_phone}</TooltipContent>
169→                </Tooltip>
170→              )}
171→              {r.candidate_email && (
172→                <Tooltip>
173→                  <TooltipTrigger asChild>
174→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
175→                      onClick={() => setEmailDialogOpen(true)}>
176→                      <Mail className="h-3.5 w-3.5" />
177→                    </Button>
178→                  </TooltipTrigger>
179→                  <TooltipContent>Email</TooltipContent>
180→                </Tooltip>
181→              )}
182→              {r.file_path && (
183→                <Tooltip>
184→                  <TooltipTrigger asChild>
185→                    <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary"
186→                      onClick={() => onDownload(r.file_path!, r.filename)}>
187→                      <FileText className="h-3.5 w-3.5" />
188→                    </Button>
189→                  </TooltipTrigger>
190→                  <TooltipContent>Download</TooltipContent>
191→                </Tooltip>
192→              )}
193→              <Tooltip>
194→                <TooltipTrigger asChild>
195→                  <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-amber-500"
196→                    onClick={() => onDismiss(r.resume_id)}>
197→                    <Archive className="h-3.5 w-3.5" />
198→                  </Button>
199→                </TooltipTrigger>
200→                <TooltipContent>Archive</TooltipContent>
201→              </Tooltip>
202→            </TooltipProvider>
203→          </div>
204→        </TableCell>
205→      </TableRow>
206→
207→      {r.candidate_email && (
208→        <EmailOutreachDialog
209→          open={emailDialogOpen}
210→          onOpenChange={setEmailDialogOpen}
211→          candidateName={r.candidate_name || r.filename}
212→          candidateEmail={r.candidate_email}
213→          jobTitle={jobTitle || "Open Position"}
214→          matchScore={Math.round(r.overall_score ?? 0)}
215→        />
216→      )}
217→    </>
218→  );
219→};
220→
221→export default CandidateRow;
222→

  1→import { Badge } from "@/components/ui/badge";
  2→import { Button } from "@/components/ui/button";
  3→import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
  4→import { ScrollArea } from "@/components/ui/scroll-area";
  5→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  6→import { Phone, Mail, FileText, Archive, MapPin } from "lucide-react";
  7→import { toast } from "sonner";
  8→import type { Result } from "@/pages/Index";
  9→import type { HiringStage } from "@/hooks/useStageTracker";
 10→
 11→import CandidateSummary from "@/components/candidate/CandidateSummary";
 12→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 13→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 14→import EducationPanel from "@/components/candidate/EducationPanel";
 15→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 16→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 17→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 18→import StageTracker from "@/components/candidate/StageTracker";
 19→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 20→import { useState } from "react";
 21→
 22→interface CandidateDetailSheetProps {
 23→  result: Result | null;
 24→  isOpen: boolean;
 25→  onClose: () => void;
 26→  jobTitle?: string | null;
 27→  formatCandidateName: (filename: string) => string;
 28→  onDownload: (filePath: string, filename: string) => void;
 29→  onDismiss: (resumeId: string) => void;
 30→  currentStage?: HiringStage | null;
 31→  stageUpdatedAt?: string | null;
 32→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 33→}
 34→
 35→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 36→  if (score >= 70) return { label: "Strong", variant: "success" };
 37→  if (score >= 40) return { label: "Good", variant: "warning" };
 38→  return { label: "Weak", variant: "destructive" };
 39→};
 40→
 41→const getScoreColor = (score: number) => {
 42→  if (score >= 70) return "bg-score-skills";
 43→  if (score >= 40) return "bg-warning";
 44→  return "bg-destructive";
 45→};
 46→
 47→const CandidateDetailSheet = ({
 48→  result: r,
 49→  isOpen,
 50→  onClose,
 51→  jobTitle,
 52→  formatCandidateName,
 53→  onDownload,
 54→  onDismiss,
 55→  currentStage,
 56→  stageUpdatedAt,
 57→  onStageChange,
 58→}: CandidateDetailSheetProps) => {
 59→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
 60→
 61→  if (!r) return null;
 62→
 63→  const strength = getStrengthLabel(r.overall_score);
 64→  const candidateName = r.candidate_name || formatCandidateName(r.filename);
 65→
 66→  return (
 67→    <>
 68→      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
 69→        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col">
 70→          {/* Header */}
 71→          <SheetHeader className="px-6 pt-6 pb-4 border-b border-border shrink-0">
 72→            <div className="flex items-start justify-between gap-4 pr-8">
 73→              <div className="space-y-1.5 min-w-0">
 74→                <SheetTitle className="text-lg font-semibold truncate">{candidateName}</SheetTitle>
 75→                <div className="flex items-center gap-2 flex-wrap">
 76→                  {r.candidate_location && (
 77→                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
 78→                      <MapPin className="h-3 w-3" /> {r.candidate_location}
 79→                    </span>
 80→                  )}
 81→                  {r.candidate_email && (
 82→                    <span className="text-xs text-muted-foreground">{r.candidate_email}</span>
 83→                  )}
 84→                </div>
 85→              </div>
 86→            </div>
 87→
 88→            {/* Score + badges + actions */}
 89→            <div className="flex items-center gap-3 pt-2 flex-wrap">
 90→              <div className="flex items-center gap-2">
 91→                <div className="flex items-center gap-1.5">
 92→                  <div className="h-2 w-16 rounded-full bg-secondary overflow-hidden">
 93→                    <div className={`h-full rounded-full ${getScoreColor(r.overall_score)}`} style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
 94→                  </div>
 95→                  <span className="text-sm font-semibold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
 96→                </div>
 97→                <Badge variant={strength.variant}>{strength.label}</Badge>
 98→              </div>
 99→
100→              <div className="flex items-center gap-0.5 ml-auto">
101→                <TooltipProvider delayDuration={300}>
102→                  {r.candidate_phone && (
103→                    <Tooltip>
104→                      <TooltipTrigger asChild>
105→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
106→                          onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
107→                          <Phone className="h-3.5 w-3.5" />
108→                        </Button>
109→                      </TooltipTrigger>
110→                      <TooltipContent>{r.candidate_phone}</TooltipContent>
111→                    </Tooltip>
112→                  )}
113→                  {r.candidate_email && (
114→                    <Tooltip>
115→                      <TooltipTrigger asChild>
116→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
117→                          onClick={() => setEmailDialogOpen(true)}>
118→                          <Mail className="h-3.5 w-3.5" />
119→                        </Button>
120→                      </TooltipTrigger>
121→                      <TooltipContent>Email candidate</TooltipContent>
122→                    </Tooltip>
123→                  )}
124→                  {r.file_path && (
125→                    <Tooltip>
126→                      <TooltipTrigger asChild>
127→                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-primary"
128→                          onClick={() => onDownload(r.file_path!, r.filename)}>
129→                          <FileText className="h-3.5 w-3.5" />
130→                        </Button>
131→                      </TooltipTrigger>
132→                      <TooltipContent>Download resume</TooltipContent>
133→                    </Tooltip>
134→                  )}
135→                  <Tooltip>
136→                    <TooltipTrigger asChild>
137→                      <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground hover:text-amber-500"
138→                        onClick={() => { onDismiss(r.resume_id); onClose(); }}>
139→                        <Archive className="h-3.5 w-3.5" />
140→                      </Button>
141→                    </TooltipTrigger>
142→                    <TooltipContent>Archive</TooltipContent>
143→                  </Tooltip>
144→                </TooltipProvider>
145→              </div>
146→            </div>
147→          </SheetHeader>
148→
149→          {/* Scrollable content */}
150→          <ScrollArea className="flex-1">
151→            <div className="px-6 py-5 space-y-5">
152→              {/* Summary */}
153→              <CandidateSummary result={r} />
154→
155→              {/* Stage Tracker */}
156→              {onStageChange && (
157→                <StageTracker
158→                  currentStage={currentStage || "applied"}
159→                  updatedAt={stageUpdatedAt}
160→                  onStageChange={(stage) => onStageChange(r.resume_id, stage)}
161→                />
162→              )}
163→
164→              {/* Strengths & Gaps */}
165→              <StrengthsGapsPanel result={r} />
166→
167→              {/* Skills | Experience | Education */}
168→              <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
169→                <SkillsDetailPanel result={r} />
170→                <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
171→                <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
172→              </div>
173→
174→              {/* JD Alignment */}
175→              <JDAlignedPanel result={r} />
176→
177→              {/* Interview Questions */}
178→              <InterviewQuestionsPanel result={r} />
179→            </div>
180→          </ScrollArea>
181→        </SheetContent>
182→      </Sheet>
183→
184→      {r.candidate_email && (
185→        <EmailOutreachDialog
186→          open={emailDialogOpen}
187→          onOpenChange={setEmailDialogOpen}
188→          candidateName={candidateName}
189→          candidateEmail={r.candidate_email}
190→          jobTitle={jobTitle || "Open Position"}
191→          matchScore={Math.round(r.overall_score ?? 0)}
192→        />
193→      )}
194→    </>
195→  );
196→};
197→
198→export default CandidateDetailSheet;
